function distributionTable(population,source='answer'){return `<table class="sr-only"><caption>Exact activation distribution bins</caption><thead><tr><th>Range</th><th>${source==='prompt'?promptRecordUnit().replace('prompt','Prompt'):responseSource()==='pair'?'Battles':'Answers'}</th></tr></thead><tbody>${population.bins.map((bin,index)=>`<tr><th>${index===population.bins.length-1?'Inclusive ':''}${mag(bin.x0)} to ${mag(bin.x1)}</th><td>${bin.count}</td></tr>`).join('')}</tbody></table>`}
