 const population=distribution.population,C=population.maxBinCount,M=population.maxMagnitude,current=distribution.current,currentText=current.state==='active'?`Current ${source==='answer'&&responseSource()==='pair'?'battle':source} · ${mag(current.magnitude)}`:current.state==='inactive'?`Current ${source==='answer'&&responseSource()==='pair'?'battle':source} · Inactive`:`Current ${source==='answer'&&responseSource()==='pair'?'battle':source} · Not available`;
