 const range=activeRange(source),selected=(kind,index)=>range?.kind===kind&&range.index===index;
 const bars=population.bins.map((bin,index)=>{const height=C?bin.count/C*90:0,label=`${mag(bin.x0)} to ${mag(bin.x1)} · ${bin.count} ${plural}`;return `<g class="hist-choice ${selected('bin',index)?'selected':''}" role="button" tabindex="${bin.count?0:-1}" aria-disabled="${!bin.count}" aria-pressed="${selected('bin',index)}" aria-label="Filter activation ${esc(label)}" data-activation-pick="bin:${index}" data-activation-source="${source}"><title>${esc(label)}</title><rect class="hist-hit" x="${25+index*32}" y="22" width="28" height="94"/><rect class="hist-bar" x="${25+index*32}" y="${116-height}" width="28" height="${height}"/></g>`}).join('');
