 const quantiles=population.active?`<div class="activation-quantiles"><div class="quantile-heading">Quantiles <span>Active ${plural} · ties together</span></div><div class="quantile-options">${population.quartiles.map((q,index)=>`<button data-activation-pick="quartile:${index}" data-activation-source="${source}" aria-pressed="${selected('quartile',index)}" ${!q.count?'disabled':''} title="${q.count} ${plural} · ${mag(q.x0)}–${mag(q.x1)}"><span>${['Lowest 25%','25–50%','50–75%','Top 25%'][index]}</span><small>${mag(q.x0)}–${mag(q.x1)}</small></button>`).join('')}</div></div>`:'';
