function duelModels(){
 const models=engine.modelRegistry,ranked=engine.battleStats().sort((a,b)=>b.battles-a.battles);
 if(!models.some(model=>model.rawId===state.duelFirst))state.duelFirst=ranked[0]?.rawId||models[0]?.rawId;
 if(!models.some(model=>model.rawId===state.duelSecond)||state.duelFirst===state.duelSecond)state.duelSecond=engine.battleStats({opponent:state.duelFirst}).filter(model=>model.rawId!==state.duelFirst&&model.battles>0).sort((a,b)=>b.battles-a.battles)[0]?.rawId||models.find(model=>model.rawId!==state.duelFirst)?.rawId;
 return [models.find(model=>model.rawId===state.duelFirst),models.find(model=>model.rawId===state.duelSecond)];
}
function duelRows(){
 if(state.duelMetric==='activity')return engine.modelConceptComparison(state.duelFirst,state.duelSecond,{source:state.duelSource,scope:state.duelScope}).rows;
 const profiles=[state.duelFirst,state.duelSecond].map((model,index)=>engine.modelConceptProfile(model,{source:state.duelSource,opponent:state.duelScope==='headToHead'?(index?state.duelFirst:state.duelSecond):null}));
 const other=new Map(profiles[1].map(row=>[row.key,row]));return profiles[0].map(row=>{const second=other.get(row.key),field=state.duelMetric==='outcome'?'score':'associationGap',metric=entry=>({share:entry?.[field]??null,active:entry?.scored||0,total:entry?.total||0,scoreKind:entry?.scoreKind,moreN:entry?.moreN,lessN:entry?.lessN});const first=metric(row),last=metric(second);return {...row,first,second:last,gap:Number.isFinite(first.share)&&Number.isFinite(last.share)&&first.scoreKind===last.scoreKind?first.share-last.share:null}});
}
