 if(!engine.models.length){$('#model-body').innerHTML=engine.answerModels.length?emptyInline('This analysis requires a fixed model pair.','Explore answers','data-nav="answers"'):emptyInline('No validated model identities are available.','Review dataset','data-nav="dataset"');return}
