function closeOverlay(restore=true,update=true){if(!state.overlay&&!overlayRoot.innerHTML)return;if(update&&state.overlay&&history.state?.overlayPush){overlayClosePending=true;history.back();return}dismissOverlay();if(update&&engine)writeURL(false);if(restore)restoreFocus();}
